	private static LmdbStoreConfig config(boolean sketches) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyBuildOnStart(true)
				.setDirectAdjacencyMaxBytes(256L << 20)
				.setValueOverlayEnabled(true)
				.setInlineLiterals(false)
				.setTripleDBSize(16L << 20)
				.setValueDBSize(16L << 20)
				.setBulkOperationSize(2)
				.setSketchEstimatorEnabled(sketches);
		config.setExperimentalQueryOptimizations(true);
		return config;
	}
